11	impl<'a> Symbol<'_, 'a> {
12	    // =========================================================================
13	    // ==================== ENABLE/DISABLE USAGE SUB-CHECKS ====================
14	    // =========================================================================
15	
16	    // NOTE(@don): all of these should be `#[inline]` and `const`. by inlining
17	    // it, rustc should be able to detect redundant flag checks and optimize
18	    // them away. Note that I haven't actually checked the assembly output to
19	    // confirm this; if you are reading this and decide to do so, please let me
20	    // know the results.
21	
22	    /// 1. Imported functions will never have calls to themselves within their
23	    ///    own declaration since they are declared outside the current module
24	    /// 2. Catch variables are always parameter-like and will therefore never have
25	    ///    a function declaration.
26	    #[inline]
27	    fn is_maybe_callable(&self) -> bool {
28	        // NOTE: imports are technically callable, but that call will never
29	        // occur within its own declaration since it's declared in another
30	        // module.
31	        const IMPORT: SymbolFlags = SymbolFlags::Import.union(SymbolFlags::TypeImport);
32	        // note: intetionally do not use `SymbolFlags::is_type` here, since that
33	        // can return `true` for values
34	        const TYPE: SymbolFlags =
35	            SymbolFlags::TypeAlias.union(SymbolFlags::TypeParameter).union(SymbolFlags::Interface);
36	        const ENUM: SymbolFlags = SymbolFlags::Enum.union(SymbolFlags::EnumMember);
37	        const NAMESPACE_LIKE: SymbolFlags =
38	            SymbolFlags::NamespaceModule.union(SymbolFlags::ValueModule);
39	
40	        !self.flags().intersects(
41	            IMPORT.union(TYPE).union(ENUM).union(NAMESPACE_LIKE).union(SymbolFlags::CatchVariable),
42	        )
43	    }
44	
45	    /// Note: we still need to check for reassignments to const variables since
46	    /// eslint's original rule requires it. Const reassignments are not a syntax
47	    /// error in JavaScript, only TypeScript.
48	    #[inline]
49	    fn is_possibly_reassignable(&self) -> bool {
50	        self.flags().is_variable()
51	    }
52	
53	    /// Check if this [`Symbol`] is definitely reassignable.
54	    ///
55	    /// Examples of non-reassignable symbols are:
56	    /// - function declarations
57	    /// - classes
58	    /// - enums
59	    /// - types (interfaces, type aliases)
60	    /// - const variables
61	    /// - imports
62	    ///
63	    /// Examples of reassinable symbols are:
64	    /// - `var` and `let` variable declarations
65	    /// - function parameters
66	    #[inline]
67	    fn is_definitely_reassignable_variable(&self) -> bool {
68	        let f = self.flags();
69	        f.is_variable() && !f.contains(SymbolFlags::ConstVariable.union(SymbolFlags::Function))
70	    }
71	
72	    /// Checks if this [`Symbol`] could be used as a type reference within its
73	    /// own declaration.
74	    ///
75	    /// This does _not_ imply this symbol is a type (negative cases include type
76	    /// imports, type parameters, etc).
77	    #[inline]
78	    fn could_have_type_reference_within_own_decl(&self) -> bool {
79	        #[rustfmt::skip]
80	        const TYPE_DECLS: SymbolFlags = SymbolFlags::TypeAlias
81	            .union(SymbolFlags::Interface)
82	            .union(SymbolFlags::Class);
83	
84	        self.flags().intersects(TYPE_DECLS)
85	    }
86	
