126	                // references can be both reads & writes. If this is only a
127	                // write, we don't need to perform any read usage checks.
128	                if !reference.is_read() {
129	                    continue;
130	                }
131	            }
132	
133	            // ======================= Type usage checks =======================
134	
135	            if reference.is_type() {
136	                // e.g. `type Foo = Array<Foo>`
137	                if do_type_self_usage_checks && self.is_type_self_usage(reference) {
138	                    continue;
139	                }
140	
141	                // ```ts
142	                // const foo = 123;
143	                // export type Foo = typeof foo
144	                // ```
145	                if options.report_vars_only_used_as_types
