119	        &self,
120	        node_id: NodeId,
121	    ) -> impl Iterator<Item = (/* parent */ AstKind<'a>, /* grandparent */ AstKind<'a>)> + Clone + '_
122	    {
123	        let parents_iter = iter::once(self.nodes().kind(node_id)).chain(
124	            self.nodes().ancestor_kinds(node_id).filter(|kind| Self::is_relevant_kind(*kind)),
125	        );
