145	    /// <https://github.com/oxc-project/oxc/issues/4739>
146	    fn derive_span(&self) -> Span {
147	        for kind in self.iter_self_and_parents().map(AstNode::kind) {
148	            match kind {
149	                AstKind::BindingIdentifier(_) => {}
150	                AstKind::BindingRestElement(rest) => return rest.span,
151	                AstKind::VariableDeclarator(decl) => return self.clean_binding_id(&decl.id),
152	                AstKind::FormalParameter(param) => return self.clean_binding_id(&param.pattern),
153	                _ => break,
154	            }
155	        }
156	        self.scoping().symbol_span(self.id)
157	    }
