169	    /// Is this [`Symbol`] exported?
170	    ///
171	    /// NOTE: does not support CJS right now.
172	    pub fn is_exported(&self) -> bool {
173	        let is_in_exportable_scope = self.is_root() || self.is_in_ts_namespace();
174	        is_in_exportable_scope && (self.is_local_exported_binding() || self.in_export_node())
175	    }
